#!/usr/bin/env node
// Generated by the e2e-perfromance-test-suite-k6 skill.
// Orchestrates a full run from a single `npm run load` invocation: seeds the
// test DB, starts the isolated backend on the test port, smoke tests, runs
// the full NFR profile, prints the scorecard, then tears the backend down --
// mirrors SKILL.md's Steps 5-10. Requires the five NFR env vars on every
// invocation (no defaults, no silent reuse), matching lib/scenarios.js's own
// requireNumber discipline -- see references/nfr-requirements.md.
//
// Usage (bash):
//   CONCURRENT_USERS=10 TPS_TARGET=20 PEAK_LOAD=40 LATENCY_P95_MS=500 TAT_P95_MS=2000 npm run load
// Usage (PowerShell):
//   $env:CONCURRENT_USERS=10; $env:TPS_TARGET=20; $env:PEAK_LOAD=40; $env:LATENCY_P95_MS=500; $env:TAT_P95_MS=2000; npm run load
import { spawn, spawnSync } from 'node:child_process';
import { existsSync, mkdirSync, readFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const K6_DIR = path.resolve(__dirname, '..');
const ROOT = path.resolve(K6_DIR, '..');
const PORT = 8833;
const BASE_URL = `http://127.0.0.1:${PORT}`;

function requireEnv(name) {
  const v = process.env[name];
  if (!v) {
    console.error(
      `Missing ${name}. This suite always requires all five NFR targets explicitly -- usage:\n` +
        '  CONCURRENT_USERS=<n> TPS_TARGET=<n> PEAK_LOAD=<n> LATENCY_P95_MS=<n> TAT_P95_MS=<n> npm run load',
    );
    process.exit(2);
  }
  return v;
}

const nfr = {
  CONCURRENT_USERS: requireEnv('CONCURRENT_USERS'),
  TPS_TARGET: requireEnv('TPS_TARGET'),
  PEAK_LOAD: requireEnv('PEAK_LOAD'),
  LATENCY_P95_MS: requireEnv('LATENCY_P95_MS'),
  TAT_P95_MS: requireEnv('TAT_P95_MS'),
};

const envKPath = path.join(K6_DIR, '.env.k6');
if (!existsSync(envKPath)) {
  console.error('Missing k6/.env.k6. Copy k6/.env.k6.example to k6/.env.k6 and set TEST_DATABASE_URL first.');
  process.exit(2);
}
const testDbUrl = readFileSync(envKPath, 'utf8').match(/^TEST_DATABASE_URL=(.*)$/m)?.[1]?.trim();
if (!testDbUrl) {
  console.error('k6/.env.k6 has no TEST_DATABASE_URL.');
  process.exit(2);
}

function resolveK6Bin() {
  const probe = spawnSync(process.platform === 'win32' ? 'where' : 'which', ['k6']);
  if (probe.status === 0) return 'k6';
  const winFallback = 'C:\\Program Files\\k6\\k6.exe';
  if (process.platform === 'win32' && existsSync(winFallback)) return winFallback;
  return 'k6';
}
const k6Bin = resolveK6Bin();

console.log('[k6] Seeding test database (server/seed.js against TEST_DATABASE_URL)...');
const seed = spawnSync('node', ['server/seed.js'], {
  cwd: ROOT,
  env: { ...process.env, DATABASE_URL: testDbUrl },
  stdio: 'inherit',
});
if (seed.status !== 0) process.exit(seed.status ?? 1);

console.log(`[k6] Starting isolated backend on :${PORT}...`);
const backend = spawn('node', ['server/index.js'], {
  cwd: ROOT,
  env: { ...process.env, DATABASE_URL: testDbUrl, PORT: String(PORT) },
  stdio: 'inherit',
});

let stopped = false;
function stopBackend() {
  if (!stopped) {
    stopped = true;
    backend.kill();
  }
}
process.on('exit', stopBackend);
process.on('SIGINT', () => {
  stopBackend();
  process.exit(1);
});

async function waitForHealth() {
  for (let i = 0; i < 30; i++) {
    try {
      const res = await fetch(`${BASE_URL}/api/health`);
      if (res.ok) return;
    } catch {
      // not up yet
    }
    await new Promise((r) => setTimeout(r, 500));
  }
  throw new Error('Backend did not become healthy on :' + PORT + ' in time.');
}

try {
  await waitForHealth();

  console.log('[k6] Smoke test...');
  const smoke = spawnSync(k6Bin, ['run', '-e', `BASE_URL=${BASE_URL}`, 'tests/smoke.js'], {
    cwd: K6_DIR,
    stdio: 'inherit',
  });
  if (smoke.status !== 0) {
    console.error('[k6] Smoke test failed -- fix wiring before running the full profile.');
    process.exitCode = smoke.status ?? 1;
  } else {
    mkdirSync(path.join(K6_DIR, 'reports'), { recursive: true });
    const ts = Math.floor(Date.now() / 1000);
    const summaryPath = `reports/summary-${ts}.json`;
    const dashboardPath = `reports/dashboard-${ts}.html`;

    console.log('[k6] Running full NFR profile...');
    const load = spawnSync(
      k6Bin,
      [
        'run',
        `--summary-export=${summaryPath}`,
        '-e', `BASE_URL=${BASE_URL}`,
        '-e', `CONCURRENT_USERS=${nfr.CONCURRENT_USERS}`,
        '-e', `TPS_TARGET=${nfr.TPS_TARGET}`,
        '-e', `PEAK_LOAD=${nfr.PEAK_LOAD}`,
        '-e', `LATENCY_P95_MS=${nfr.LATENCY_P95_MS}`,
        '-e', `TAT_P95_MS=${nfr.TAT_P95_MS}`,
        'tests/load-test.js',
      ],
      {
        cwd: K6_DIR,
        env: { ...process.env, K6_WEB_DASHBOARD: 'true', K6_WEB_DASHBOARD_EXPORT: dashboardPath },
        stdio: 'inherit',
      },
    );

    spawnSync(
      'node',
      [
        'scripts/nfr-report.mjs',
        summaryPath,
        nfr.CONCURRENT_USERS,
        nfr.TPS_TARGET,
        nfr.PEAK_LOAD,
        nfr.LATENCY_P95_MS,
        nfr.TAT_P95_MS,
      ],
      { cwd: K6_DIR, stdio: 'inherit' },
    );

    console.log(`[k6] Dashboard: k6/${dashboardPath}`);
    process.exitCode = load.status ?? 0;
  }
} finally {
  stopBackend();
}
